// ------------------------------------------------------------ geometry
type Fn = (x: number, y: number) => [number, number];

function mapPath(d: string, fn: Fn): string {
  const tokens = d.match(/[MLCZ]|-?\d*\.?\d+/g) ?? [];
  const out: string[] = [];
  let i = 0;
  while (i < tokens.length) {
    const tok = tokens[i];
    if (/[MLCZ]/.test(tok)) {
      out.push(tok);
      i++;
      continue;
    }
    const [x, y] = fn(parseFloat(tok), parseFloat(tokens[i + 1]));
    out.push(`${x.toFixed(1)} ${y.toFixed(1)}`);
    i += 2;
  }
  return out.join(' ');
}

const mirror: Fn = (x, y) => [500 - x, y];

/** Smoothstep interpolation through (y, k) keyframes. */
function smoothKeys(y: number, keys: [number, number][]): number {
  for (let i = 1; i < keys.length; i++) {
    const [y1, k1] = keys[i];
    const [y0, k0] = keys[i - 1];
    if (y <= y1) {
      const t = (y - y0) / (y1 - y0);
      return k0 + (k1 - k0) * t * t * (3 - 2 * t);
    }
  }
  return keys[keys.length - 1][1];
}

// Build pass — bodybuilder mass: a broad torso, solid waist and big legs
// (width multiplier by height), arms widened as one unit so they stay
// straight, and a smaller head scaled toward the chin.
const BUILD_K: [number, number][] = [
  [0, 1], [128, 1], [168, BUILD_ARM], [300, BUILD_ARM], [400, 1.19], [470, 1.16], [560, 1.12], [700, 1.07], [900, 1.04],
];
// Arms get thicker around their own axis (shoulder → wrist), ramping in
// below the deltoid so the shoulder seam stays exact.
const ARM_AXIS = { sx: 142, sy: 222, wx: 50, wy: 456 };
const ARM_THICK = 1.24;
function thickenArm(x: number, y: number): [number, number] {
  const { sx, sy, wx, wy } = ARM_AXIS;
  const dx = wx - sx;
  const dy = wy - sy;
  const t = ((x - sx) * dx + (y - sy) * dy) / (dx * dx + dy * dy);
  const ramp = Math.min(1, Math.max(0, (t - 0.22) / 0.2));
  const k = 1 + (ARM_THICK - 1) * ramp * ramp * (3 - 2 * ramp);
  const fx = sx + t * dx;
  const fy = sy + t * dy;
  return [fx + (x - fx) * k, fy + (y - fy) * k];
}

function build(zone: Part['zone']): Fn {
  if (zone === 'head') return (x, y) => [250 + (x - 250) * HEAD_SCALE, 130 + (y - 130) * HEAD_SCALE];
  if (zone === 'arm')
    return (x, y) => {
      const [tx, ty] = thickenArm(x, y);
      return [250 + (tx - 250) * BUILD_ARM, ty];
    };
  return (x, y) => [250 + (x - 250) * smoothKeys(y, BUILD_K), y];
}

// Female silhouette: width multiplier by height (piecewise, smoothed).
const FEMALE_K: [number, number][] = [
  [0, 0.93], [130, 0.93], [176, 0.86], [282, 0.88], [395, 0.85], [462, 1.0], [540, 1.06], [662, 1.01], [900, 0.97],
];
const femaleK = (y: number): number => smoothKeys(y, FEMALE_K);
const FEMALE_ARM = 0.87;
const femaleWarp: Fn = (x, y) => [250 + (x - 250) * femaleK(y), y];

// ------------------------------------------------------------- render
export interface AnatomyOptions {
  label?: (m: Muscle) => string;
  interactive?: boolean;
}

/** Render one view as an <svg> string. Muscle groups are <g data-muscle>. */
export function renderAnatomy(view: View, body: BodyType, opts: AnatomyOptions = {}): string {
  const parts = (view === 'front' ? FRONT : BACK).filter((p) => !p.only || p.only === body);
  const shape = (zone: Part['zone']): Fn => {
    const b = build(zone);
    if (body !== 'female') return b;
    // Female arms follow the narrower shoulders as one rigid unit.
    if (zone === 'arm') return (x, y) => b(250 + (x - 250) * FEMALE_ARM, y);
    return (x, y) => b(...femaleWarp(x, y));
  };
  const groups = new Map<Muscle, string[]>();
  const layers: Record<Exclude<Kind, 'muscle'>, string[]> = { back: [], skin: [], minor: [], line: [] };

  for (const p of parts) {
    const warp = shape(p.zone);
    const ds = [mapPath(p.d, warp)];
    // Shape the authored left half first, then mirror (all passes are symmetric).
    if (!p.center) ds.push(mapPath(p.d, (x, y) => mirror(...warp(x, y))));
    if (p.m) {
      const list = groups.get(p.m) ?? [];
      list.push(...ds);
      groups.set(p.m, list);
    } else {
      layers[p.kind === 'line' || p.kind === 'minor' || p.kind === 'back' ? p.kind : 'skin'].push(...ds);
    }
  }

  const path = (cls: string) => (d: string) => `<path class="${cls}" d="${d}"/>`;
  const muscles = [...groups.entries()]
    .map(([m, ds]) => {
      const label = opts.label ? opts.label(m) : m;
      const a11y = opts.interactive
        ? ` role="button" tabindex="0" aria-label="${label.replace(/"/g, '&quot;')}" aria-pressed="false"`
        : '';
      return `<g class="mg" data-muscle="${m}"${a11y}>${ds.map(path('mp-m')).join('')}</g>`;
    })
    .join('');

  return `<svg class="anatomy" viewBox="-36 0 572 900" xmlns="http://www.w3.org/2000/svg" data-view="${view}" role="group">
    <g class="mp-back-layer">${layers.back.map(path('mp-back')).join('')}</g>
    <g class="mp-skin-layer">${layers.skin.map(path('mp-skin')).join('')}</g>
    <g class="mp-minor-layer">${layers.minor.map(path('mp-minor')).join('')}</g>
    <g class="mp-muscles">${muscles}</g>
    <g class="mp-line-layer" aria-hidden="true">${layers.line.map(path('mp-line')).join('')}</g>
  </svg>`;
}
